insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_breathtaking','breathtaking','adjective','extremely beautiful, impressive or exciting','[{"senseId":"breathtaking_1","meaning":"extremely beautiful, impressive or exciting","acceptedParaphrases":["stunning","awe-inspiring"],"masteryContexts":[{"contextId":"u4_01_breathtaking_meaning","text":"From the top of the cable car, we enjoyed a breathtaking view of the snow-covered valley.","meaning":"extremely beautiful and impressive","wrongMeanings":["extremely cold and windy","extremely high and dangerous","extremely quiet and empty"]},{"contextId":"u4_01_breathtaking_paraphrase","text":"The coastal railway journey is breathtaking, especially at sunset when the sea turns gold.","meaning":"so beautiful or exciting that it amazes you","wrongMeanings":["so tiring or boring that it exhausts you","so slow or crowded that it annoys you","so loud or sudden that it frightens you"]}],"situationDistractors":["The bus station was dirty and grey, and the view from the window was of a car park.","The motorway was long and flat, and there was nothing interesting to see for hours.","The traveller slept through the whole journey and saw none of the scenery.","The bus was late, so we waited at the stop for forty minutes in the rain.","The guide gave us a map and told us to meet at the station at noon.","The airport café was busy, and the queue for coffee stretched past the shop."],"gapDistractors":[{"contextId":"u4_01_breathtaking_gap_1","answer":"breathtaking","wrong":["noisy","crowded","muddy"]},{"contextId":"u4_01_breathtaking_gap_2","answer":"breathtaking","wrong":["crowded","tiring","muddy"]},{"contextId":"u4_01_breathtaking_gap_3","answer":"breathtaking","wrong":["tiring","muddy","crowded"]}],"spellingErrors":["brethtaking","breathtakeing","breathtaiking","breathtacking","breaththaking","breathaking"],"masteryPassages":[{"passageId":"u4_01_breathtaking_passage_1","contextId":"u4_01_breathtaking_gap_1","text":"The mountain railway climbs slowly above the clouds. From the carriage window, travellers see a ____ view of snowy peaks and deep green valleys.","answer":"breathtaking"},{"passageId":"u4_01_breathtaking_passage_2","contextId":"u4_01_breathtaking_gap_2","text":"We reached the top of the pass just as the sun was rising. The scene was so ____ that nobody in the car spoke for several minutes.","answer":"breathtaking"}],"contextDependentParaphrases":[],"wrongParaphrases":["frightening","exhausting","disappointing"],"misleadingDistractors":["dangerous and difficult to reach","very tiring and uncomfortable","cheap and easy to find"]}]'::jsonb,'[]'::jsonb,'["breathtaking view","breathtaking scenery","absolutely breathtaking"]'::jsonb,'live'),
('vocab_comfort','comfort','noun','a state of being physically relaxed and free from pain or difficulty','[{"senseId":"comfort_1","meaning":"a state of being physically relaxed and free from pain or difficulty","acceptedParaphrases":["physical ease","being relaxed and at ease"],"masteryContexts":[{"contextId":"u4_02_comfort_meaning","text":"The new coach has wide seats and extra legroom, so passengers can travel in comfort even on long journeys.","meaning":"a relaxed state without pain or difficulty","wrongMeanings":["a feeling of safety without danger or risk","a level of speed without delay or noise","an amount of money without debt or cost"]},{"contextId":"u4_02_comfort_paraphrase","text":"Many passengers choose the train for its comfort, because they can stretch their legs and move around.","meaning":"physical ease and relaxation","wrongMeanings":["physical strength and fitness","speed and efficiency","safety and security"]}],"situationDistractors":["The seat was hard and narrow, and the passenger could not stretch his legs for ten hours.","The bus was so crowded that people stood pressed together and could hardly move.","The train was freezing, and the windows would not close.","The train arrived late and the platform was crowded with people carrying heavy bags.","The mechanic changed the tyres and checked the brakes before the long drive.","The ticket was cheap, so the family booked seats for all four of them."],"gapDistractors":[{"contextId":"u4_02_comfort_gap_1","answer":"comfort","wrong":["danger","fear","pain"]},{"contextId":"u4_02_comfort_gap_2","answer":"comfort","wrong":["smell","weight","noise"]},{"contextId":"u4_02_comfort_gap_3","answer":"comfort","wrong":["speed","money","noise"]}],"spellingErrors":["comfurt","comfot","confort","comfert","cumfort","comfortt"],"wordFamilyForms":[{"form":"comfort","partOfSpeech":"noun","example":"The seats were designed for the comfort of long-distance passengers.","pedagogicallyUseful":true},{"form":"comfortable","partOfSpeech":"adjective","example":"The new coach seats are wide, soft and very comfortable.","pedagogicallyUseful":true},{"form":"uncomfortable","partOfSpeech":"adjective","example":"The narrow seat was so uncomfortable that I could not sleep.","pedagogicallyUseful":true},{"form":"comfortably","partOfSpeech":"adverb","example":"We sat comfortably in the carriage and watched the fields go by.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u4_02_comfort_passage_1","contextId":"u4_02_comfort_gap_1","text":"The airline has fitted its long-haul planes with wider seats and more legroom. As a result, people can now travel in ____ even on a twelve-hour flight.","answer":"comfort"},{"passageId":"u4_02_comfort_passage_2","contextId":"u4_02_comfort_gap_2","text":"Choosing a new family car was not easy. My mother wanted soft seats and plenty of space for her legs, because she spends hours on the road every day. For her, ____ was more important than speed.","answer":"comfort"}],"contextDependentParaphrases":[],"wrongParaphrases":["physical strength","daily routine","personal safety"],"misleadingDistractors":["a feeling of excitement before a journey","a lack of space for people or luggage","the money paid for a ticket"]}]'::jsonb,'["comfortable","uncomfortable","comfortably"]'::jsonb,'["travel in comfort","passenger comfort","comfort and safety"]'::jsonb,'live'),
('vocab_reality','reality','noun','the true situation or what actually exists, not what is imagined or hoped for','[{"senseId":"reality_1","meaning":"the true situation or what actually exists, not what is imagined or hoped for","acceptedParaphrases":["the true situation","how things actually are"],"masteryContexts":[{"contextId":"u4_03_reality_meaning","text":"Students imagine that driving a bus is easy, but the reality is long hours and heavy traffic.","meaning":"the true situation, not what people imagine","wrongMeanings":["the usual routine that people follow","the main reason that people give","the best result that people expect"]},{"contextId":"u4_03_reality_paraphrase","text":"In reality, the new tunnel took twelve years to build, not the five that the engineers had promised.","meaning":"what actually happened","wrongMeanings":["what was publicly promised","what might happen later","what most people expected"]}],"situationDistractors":["The young pilot dreamed of flying a jumbo jet one day and drew pictures of aeroplanes all week.","The engineers made a detailed plan for the new bridge and showed it to the mayor.","The writer invented a story about a train that could travel through time.","The bus company changed its timetable in the spring and printed new leaflets.","The pilot checked the weather report and spoke to the control tower.","A cyclist stopped at the traffic lights and waited for them to turn green."],"gapDistractors":[{"contextId":"u4_03_reality_gap_1","answer":"reality","wrong":["dream","promise","plan"]},{"contextId":"u4_03_reality_gap_2","answer":"reality","wrong":["dream","hope","promise"]},{"contextId":"u4_03_reality_gap_3","answer":"reality","wrong":["secret","silence","danger"]}],"spellingErrors":["realaty","reallity","realitty","relaity","raelity","realiti"],"wordFamilyForms":[{"form":"reality","partOfSpeech":"noun","example":"The reality of the job is long hours and heavy traffic.","pedagogicallyUseful":true},{"form":"real","partOfSpeech":"adjective","example":"The engineers needed to know whether the crack was a real danger or just a mark in the paint.","pedagogicallyUseful":true},{"form":"realistic","partOfSpeech":"adjective","example":"It is not realistic to expect every train to arrive on time in heavy snow.","pedagogicallyUseful":true},{"form":"realise","partOfSpeech":"verb","example":"Many drivers do not realise how tired they are until they stop.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u4_03_reality_passage_1","contextId":"u4_03_reality_gap_1","text":"The holiday brochure showed an empty beach and a quiet hotel. The ____ was very different: the beach was packed and the hotel stood beside a busy motorway.","answer":"reality"},{"passageId":"u4_03_reality_passage_2","contextId":"u4_03_reality_gap_2","text":"Many children dream of becoming airline pilots and travelling the world. In ____, the job involves long hours, strict rules and time away from family.","answer":"reality"}],"contextDependentParaphrases":[],"wrongParaphrases":["the main problem","the usual routine","the best result"],"misleadingDistractors":["a dream about what might happen","a plan made before a journey","a story told to entertain people"]}]'::jsonb,'["real","realistic","realise"]'::jsonb,'["harsh reality","in reality","face reality"]'::jsonb,'live'),
('vocab_toughest','toughest','adjective','most difficult to do or to deal with','[{"senseId":"toughest_1","meaning":"most difficult to do or to deal with","acceptedParaphrases":["hardest","most demanding"],"masteryContexts":[{"contextId":"u4_04_toughest_meaning","text":"The toughest section of the railway was the tunnel through the mountain, which took nine years to dig.","meaning":"the most difficult to build or complete","wrongMeanings":["the most expensive to plan or finance","the most dangerous to enter or leave","the most famous to visit or photograph"]},{"contextId":"u4_04_toughest_paraphrase","text":"For many drivers, the toughest challenge on the road is staying alert during a long night shift.","meaning":"the hardest to deal with","wrongMeanings":["the longest to wait for","the easiest to prepare for","the most boring to listen to"]}],"situationDistractors":["The final stage of the race was short and easy, and everyone finished in a good mood.","The route was flat, the weather was perfect and the cyclists enjoyed the ride.","The driver found the journey so simple that he arrived an hour early.","The tourists took photographs of the old bridge and bought postcards at the kiosk.","The ferry left the harbour at eight o’clock and arrived on the island before lunch.","The taxi driver carried the suitcases to the hotel entrance."],"gapDistractors":[{"contextId":"u4_04_toughest_gap_1","answer":"toughest","wrong":["easiest","shortest","cheapest"]},{"contextId":"u4_04_toughest_gap_2","answer":"toughest","wrong":["simplest","cheapest","fastest"]},{"contextId":"u4_04_toughest_gap_3","answer":"toughest","wrong":["shortest","cheapest","easiest"]}],"spellingErrors":["tuffest","toughist","toughtest","touhgest","toughes","tougest"],"masteryPassages":[{"passageId":"u4_04_toughest_passage_1","contextId":"u4_04_toughest_gap_1","text":"The race crosses three countries in five days. For most riders, the ____ stage is the last one, which climbs steeply for sixty kilometres.","answer":"toughest"},{"passageId":"u4_04_toughest_passage_2","contextId":"u4_04_toughest_gap_2","text":"Building the railway through the mountains was extremely difficult. Engineers agree that the ____ challenge was digging a tunnel through solid rock.","answer":"toughest"}],"contextDependentParaphrases":[],"wrongParaphrases":["fastest","cheapest","oldest"],"misleadingDistractors":["most exciting to watch","most expensive to organise","most popular with visitors"]}]'::jsonb,'[]'::jsonb,'["toughest challenge","toughest test","toughest part"]'::jsonb,'live'),
('vocab_storeys','storeys','noun','the different floors or levels of a building','[{"senseId":"storeys_1","meaning":"the different floors or levels of a building","acceptedParaphrases":["floors","levels"],"masteryContexts":[{"contextId":"u4_05_storeys_meaning","text":"The airport hotel has twelve storeys, and every room on the top floors has a view of the runway.","meaning":"the floors or levels of a building","wrongMeanings":["the rooms or flats inside a building","the windows or doors of a building","the lifts or stairs in a building"]},{"contextId":"u4_05_storeys_paraphrase","text":"The new ferry terminal is only three storeys high, so it does not block the view of the harbour.","meaning":"levels of a building, counted from the ground upwards","wrongMeanings":["sections of a building, counted from left to right","rooms of a building, counted from the entrance","walls of a building, counted from the outside"]}],"situationDistractors":["The tourists queued for the lift, which took them from the ground to the viewing platform.","The guide pointed at the tall tower and said that it was the tallest in the city.","The engineers measured the height of the bridge in metres.","The travellers waited on the platform until the express train arrived.","The pilot welcomed everyone on board and described the weather at the destination.","The coach stopped at a service area so that people could buy drinks."],"gapDistractors":[{"contextId":"u4_05_storeys_gap_1","answer":"storeys","wrong":["tickets","engines","wheels"]},{"contextId":"u4_05_storeys_gap_2","answer":"storeys","wrong":["rooms","lifts","doors"]},{"contextId":"u4_05_storeys_gap_3","answer":"storeys","wrong":["tickets","engines","tourists"]}],"spellingErrors":["stories","storeis","storyes","storees","storrys","storys"],"masteryPassages":[{"passageId":"u4_05_storeys_passage_1","contextId":"u4_05_storeys_gap_1","text":"The new airport hotel is very tall. With forty ____, it can be seen from the runway several kilometres away.","answer":"storeys"},{"passageId":"u4_05_storeys_passage_2","contextId":"u4_05_storeys_gap_2","text":"The old railway station is only two ____ high. Next to it, the new office tower rises above the whole city.","answer":"storeys"}],"contextDependentParaphrases":[],"wrongParaphrases":["rooms","walls","roofs"],"misleadingDistractors":["the rooms where passengers wait","the lifts and stairs inside a tower","the shops inside a building"]}]'::jsonb,'[]'::jsonb,'["several storeys","two storeys","storeys high"]'::jsonb,'live'),
('vocab_accommodate','accommodate','verb','to have enough space or room for people or things','[{"senseId":"accommodate_1","meaning":"to have enough space or room for people or things","acceptedParaphrases":["hold","have room for"],"masteryContexts":[{"contextId":"u4_06_accommodate_meaning","text":"The new stadium can accommodate eighty thousand fans, and extra trains run after every match.","meaning":"have enough space for","wrongMeanings":["carry safely to another place","provide food and drink for","keep out of the building"]},{"contextId":"u4_06_accommodate_paraphrase","text":"The minibus is small and cannot accommodate more than eight people with their luggage.","meaning":"have enough room to hold","wrongMeanings":["have enough power to move","have enough money to buy","have enough time to wait for"]}],"situationDistractors":["The driver asked everyone to show their tickets before getting on.","The airline moved a group of travellers to a later flight because of bad weather.","The bus left the station ten minutes late because of heavy traffic.","The cyclist repaired a puncture beside the road and then continued up the hill.","The tourists admired the old harbour and took photographs of the fishing boats.","The railway company published a new timetable for the summer months."],"gapDistractors":[{"contextId":"u4_06_accommodate_gap_1","answer":"accommodate","wrong":["repair","inspect","sell"]},{"contextId":"u4_06_accommodate_gap_2","answer":"accommodate","wrong":["repair","inspect","lose"]},{"contextId":"u4_06_accommodate_gap_3","answer":"accommodate","wrong":["repair","ignore","predict"]}],"spellingErrors":["acommodate","accomodate","accommadate","acomodate","accommodete","accomodete"],"masteryPassages":[{"passageId":"u4_06_accommodate_passage_1","contextId":"u4_06_accommodate_gap_1","text":"The new ferry is enormous. It can ____ two hundred cars, five coaches and about one thousand passengers.","answer":"accommodate"},{"passageId":"u4_06_accommodate_passage_2","contextId":"u4_06_accommodate_gap_2","text":"The old bus station was far too small for the growing city. Last year the council rebuilt it with extra platforms to ____ the additional buses.","answer":"accommodate"}],"contextDependentParaphrases":[],"wrongParaphrases":["repair","sell","follow"],"misleadingDistractors":["to carry people from one place to another","to pay for people to travel","to stop people from entering"],"grammarForms":{"base":"accommodate","thirdPerson":"accommodates","past":"accommodated","pastParticiple":"accommodated","ing":"accommodating"}}]'::jsonb,'[]'::jsonb,'["accommodate passengers","easily accommodate","accommodate up to"]'::jsonb,'live'),
('vocab_luxury','luxury','noun','great comfort provided by expensive things','[{"senseId":"luxury_1","meaning":"great comfort provided by expensive things","acceptedParaphrases":["lavish surroundings","expensive enjoyment"],"masteryContexts":[{"contextId":"u4_07_luxury_meaning","text":"The cruise ship offers passengers a life of luxury, with private balconies and five-star restaurants.","meaning":"great comfort provided by expensive things","wrongMeanings":["great speed provided by powerful engines","great safety provided by careful rules","great freedom provided by long holidays"]},{"contextId":"u4_07_luxury_paraphrase","text":"For many families, a holiday abroad is a luxury that they can enjoy only once every few years.","meaning":"something enjoyable and expensive that is not necessary","wrongMeanings":["something useful and cheap that is easy to find","something essential and costly that people must buy","something enjoyable and rare that is hard to find"]}],"situationDistractors":["The family brought sandwiches and sat on a hard wooden bench in the station.","The bus was cheap and simple, with plastic seats and no heating.","The traveller needed to get to work every day, so he bought a monthly pass.","The pilot checked the instruments carefully before the aeroplane left the runway.","The tram stopped at the market square, and several shoppers got off.","The mechanic explained that the engine needed a new filter."],"gapDistractors":[{"contextId":"u4_07_luxury_gap_1","answer":"luxury","wrong":["danger","poverty","fear"]},{"contextId":"u4_07_luxury_gap_2","answer":"luxury","wrong":["necessity","problem","habit"]},{"contextId":"u4_07_luxury_gap_3","answer":"luxury","wrong":["problem","danger","delay"]}],"spellingErrors":["luxery","luxary","lugzury","luxurry","luxuary","luxeri"],"wordFamilyForms":[{"form":"luxury","partOfSpeech":"noun","example":"The cruise offers every luxury, from heated pools to private balconies.","pedagogicallyUseful":true},{"form":"luxurious","partOfSpeech":"adjective","example":"The hotel suites were large, quiet and extremely luxurious.","pedagogicallyUseful":true,"altExample":"The airline has introduced a luxurious new lounge for first-class travellers."},{"form":"luxuriously","partOfSpeech":"adverb","example":"The first-class cabin was luxuriously decorated with leather seats and soft lights.","pedagogicallyUseful":true,"altExample":"The private jet was luxuriously furnished with deep sofas and a small bar."}],"masteryPassages":[{"passageId":"u4_07_luxury_passage_1","contextId":"u4_07_luxury_gap_1","text":"The cruise ship has five restaurants, a theatre and private balconies. Guests who pay for the top cabins live in ____ for the whole voyage.","answer":"luxury"},{"passageId":"u4_07_luxury_passage_2","contextId":"u4_07_luxury_gap_2","text":"Most of the families in our village cannot afford foreign holidays. For them, a week at the seaside is a ____ that they enjoy once a year.","answer":"luxury"}],"contextDependentParaphrases":[],"wrongParaphrases":["plain surroundings","heavy luggage","cheap holidays"],"misleadingDistractors":["a simple, cheap way of travelling","the basic things that people need to live","a short rest taken during a journey"]}]'::jsonb,'["luxurious","luxuriously"]'::jsonb,'["luxury hotel","in luxury","luxury cruise"]'::jsonb,'live'),
('vocab_altitude','altitude','noun','the height of a place or object above sea level','[{"senseId":"altitude_1","meaning":"the height of a place or object above sea level","acceptedParaphrases":["height above sea level","elevation"],"masteryContexts":[{"contextId":"u4_08_altitude_meaning","text":"At high altitude, the air is thinner, so climbers and pilots need extra oxygen.","meaning":"height above sea level","wrongMeanings":["distance from the nearest city","speed relative to the ground","depth below the ground"]},{"contextId":"u4_08_altitude_paraphrase","text":"The cable car carries visitors from the village to a viewing point at an altitude of three thousand metres.","meaning":"the height of a place above sea level","wrongMeanings":["the distance of a place from the coast","the temperature of a place in winter","the size of a place on the map"]}],"situationDistractors":["The ship sailed for two days across the ocean without stopping.","The pilot told the passengers that the flight would take three hours and ten minutes.","The engineer measured the depth of the tunnel under the river.","The family queued at the ticket office to buy tickets for the evening train.","The taxi driver took a shortcut through the old town to avoid the traffic.","A cyclist waved from the pavement as the coach drove slowly past."],"gapDistractors":[{"contextId":"u4_08_altitude_gap_1","answer":"altitude","wrong":["expense","engine","island"]},{"contextId":"u4_08_altitude_gap_2","answer":"altitude","wrong":["island","engine","airport"]},{"contextId":"u4_08_altitude_gap_3","answer":"altitude","wrong":["noise","price","colour"]}],"spellingErrors":["altatude","altitute","altitud","altidude","alltitude","altituide"],"masteryPassages":[{"passageId":"u4_08_altitude_passage_1","contextId":"u4_08_altitude_gap_1","text":"The aeroplane left the runway and climbed steadily. After twenty minutes, the pilot announced that we had reached a cruising ____ of eleven thousand metres.","answer":"altitude"},{"passageId":"u4_08_altitude_passage_2","contextId":"u4_08_altitude_gap_2","text":"Many climbers feel dizzy and tired high in the mountains. This happens because the air is thinner at great ____, so there is less oxygen to breathe.","answer":"altitude"}],"contextDependentParaphrases":[],"wrongParaphrases":["distance from the coast","speed over the ground","depth below the surface"],"misleadingDistractors":["the distance between two cities","the speed of a moving vehicle","the depth of a lake or sea"]}]'::jsonb,'[]'::jsonb,'["high altitude","cruising altitude","gain altitude"]'::jsonb,'live'),
('vocab_landscape','landscape','noun','all the natural scenery that can be seen across an area, such as hills, fields and rivers','[{"senseId":"landscape_1","meaning":"all the natural scenery that can be seen across an area, such as hills, fields and rivers","acceptedParaphrases":["scenery","view of the countryside"],"masteryContexts":[{"contextId":"u4_09_landscape_meaning","text":"The Trans-Siberian railway passes through a changing landscape of forests, lakes and endless plains.","meaning":"all the natural features that can be seen across an area","wrongMeanings":["all the roads and tracks that cross an area","all the buildings that have been built in an area","all the maps that have been drawn of an area"]},{"contextId":"u4_09_landscape_paraphrase","text":"The new motorway has changed the landscape of the valley, which was once quiet farmland.","meaning":"the appearance of an area of countryside","wrongMeanings":["the history of an area of countryside","the size of an area of countryside","the owner of an area of countryside"]}],"situationDistractors":["The tourists studied a map of the region and marked the roads in red.","The guide showed them a painting of the mountains inside the museum.","The driver parked beside the road and checked the tyres.","The mechanic repaired the engine and then washed the car.","At the airport, a security officer checked every bag before the flight boarded.","The bus stopped outside the museum, and the whole group got off."],"gapDistractors":[{"contextId":"u4_09_landscape_gap_1","answer":"landscape","wrong":["timetable","ticket","engine"]},{"contextId":"u4_09_landscape_gap_2","answer":"landscape","wrong":["weight","price","speed"]},{"contextId":"u4_09_landscape_gap_3","answer":"landscape","wrong":["timetable","ticket","engine"]}],"spellingErrors":["landscap","lanscape","landscpae","landskape","landscaipe","landscaep"],"masteryPassages":[{"passageId":"u4_09_landscape_passage_1","contextId":"u4_09_landscape_gap_1","text":"The road runs for two hundred kilometres through the north of the country. Drivers pass lakes, hills and farms, and the ____ changes every few minutes.","answer":"landscape"},{"passageId":"u4_09_landscape_passage_2","contextId":"u4_09_landscape_gap_2","text":"Wind turbines now stand on many of the hills near the coast. Some residents think they spoil the ____, while others believe they are a good source of clean energy.","answer":"landscape"}],"contextDependentParaphrases":[],"wrongParaphrases":["wildlife","weather","farming"],"misleadingDistractors":["a map showing roads and railways","a painting hung on a station wall","a road that crosses an open area"]}]'::jsonb,'[]'::jsonb,'["rural landscape","changing landscape","stunning landscape"]'::jsonb,'live'),
('vocab_passenger','passenger','noun','a person who travels in a vehicle, aircraft or ship but is not the driver or crew','[{"senseId":"passenger_1","meaning":"a person who travels in a vehicle, aircraft or ship but is not the driver or crew","acceptedParaphrases":["person travelling on board","traveller on board"],"masteryContexts":[{"contextId":"u4_10_passenger_meaning","text":"The bus driver waited until every passenger had found a seat before he moved off.","meaning":"a person who travels in a vehicle but does not drive it","wrongMeanings":["a person who drives a vehicle but does not own it","a person who repairs a vehicle but does not use it","a person who waits for a vehicle but does not board it"]},{"contextId":"u4_10_passenger_paraphrase","text":"A passenger on the night train described the journey as the most relaxing of her life.","meaning":"a traveller who is not the driver or crew","wrongMeanings":["an inspector who works for the driver or crew","a visitor who waits to meet the driver or crew","a guard who travels with the driver or crew"]}],"situationDistractors":["The driver checked the engine and filled the tank with fuel before leaving.","The ticket inspector walked through the carriages checking the tickets.","The pilot told the control tower that the aeroplane was ready to take off.","The mechanic repaired the engine while the owner waited in the garage.","The road was closed for a week because of a landslide near the tunnel.","The railway company bought twenty new trains for the northern routes."],"gapDistractors":[{"contextId":"u4_10_passenger_gap_1","answer":"passenger","wrong":["mechanic","engineer","guard"]},{"contextId":"u4_10_passenger_gap_2","answer":"passenger","wrong":["sailor","captain","cook"]},{"contextId":"u4_10_passenger_gap_3","answer":"passenger","wrong":["mechanic","pilot","guard"]}],"spellingErrors":["pasenger","passanger","passeger","passangar","pasanger","pessenger"],"masteryPassages":[{"passageId":"u4_10_passenger_passage_1","contextId":"u4_10_passenger_gap_1","text":"The bus driver stopped beside the school gate. A young ____ climbed on, showed her pass and found a seat near the window.","answer":"passenger"},{"passageId":"u4_10_passenger_passage_2","contextId":"u4_10_passenger_gap_2","text":"The flight attendant checked that every ____ had fastened a seat belt. Then the aeroplane began to move slowly towards the runway.","answer":"passenger"}],"contextDependentParaphrases":[],"wrongParaphrases":["person driving the vehicle","person selling the tickets","person repairing the engine"],"misleadingDistractors":["a person who drives a bus or taxi","a person who sells tickets at a station","a person who checks luggage at an airport"]}]'::jsonb,'[]'::jsonb,'["passenger seat","passenger train","fellow passenger"]'::jsonb,'live')
