('u4_idea_breathtaking',4,'idea_set','{"originalIdea":"The view from the top of the mountain railway was breathtaking.","accurateParaphrases":["The scenery seen from the top of the mountain railway was stunning.","The top of the mountain railway offered an amazingly beautiful view.","From the highest point of the mountain railway, the view was truly impressive."],"meaningInvariants":[{"type":"degree","value":"extremely impressive"}],"distractors":[{"text":"The view from the top of the mountain railway was slightly disappointing.","misconceptionCategory":"polarity_change"},{"text":"The view from the top of the mountain railway was somewhat pleasant.","misconceptionCategory":"degree_change"},{"text":"The journey up the mountain railway was long and tiring.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_breathtaking"],"primaryEvidenceTargetId":"vocab_breathtaking"}'::jsonb,'live'),
('u4_idea_comfort',4,'idea_set','{"originalIdea":"The new coaches allow passengers to travel in comfort.","accurateParaphrases":["The new coaches let travellers enjoy a relaxed, pain-free journey.","Passengers on the new coaches can make their journey in physical ease.","The new coaches make long journeys easy and pleasant for travellers."],"meaningInvariants":[{"type":"cause_effect","value":"the new coaches make the journey relaxed"}],"distractors":[{"text":"The new coaches force passengers to travel in discomfort.","misconceptionCategory":"polarity_change"},{"text":"The new coaches allow passengers to travel at high speed.","misconceptionCategory":"meaning_confusion"},{"text":"Only passengers who pay extra can travel in a relaxed way on the new coaches.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_comfort"],"primaryEvidenceTargetId":"vocab_comfort"}'::jsonb,'live'),
('u4_idea_reality',4,'idea_set','{"originalIdea":"The reality of life as a pilot is very different from what most people imagine.","accurateParaphrases":["The true situation for pilots is not at all what most people expect.","Life as a pilot is actually quite unlike the picture most people have.","What being a pilot is really like differs greatly from what most people think."],"meaningInvariants":[{"type":"comparison","value":"differs greatly from what people imagine"}],"distractors":[{"text":"The reality of life as a pilot is exactly what most people imagine.","misconceptionCategory":"polarity_change"},{"text":"The reality of life as a pilot is slightly different from what most people imagine.","misconceptionCategory":"degree_change"},{"text":"The dream of life as a pilot is very different from what most people imagine.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_reality"],"primaryEvidenceTargetId":"vocab_reality"}'::jsonb,'live'),
('u4_idea_toughest',4,'idea_set','{"originalIdea":"The toughest part of the journey was crossing the mountains in winter.","accurateParaphrases":["The hardest section of the trip was getting over the mountains in winter.","Crossing the mountains in winter was the most difficult stage of the journey.","The most demanding part of the trip was travelling over the mountains in winter."],"meaningInvariants":[{"type":"degree","value":"the most difficult part"}],"distractors":[{"text":"The easiest part of the journey was crossing the mountains in winter.","misconceptionCategory":"polarity_change"},{"text":"The first part of the journey was crossing the mountains in winter.","misconceptionCategory":"time_change"},{"text":"The toughest part of the journey was crossing the desert in summer.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_toughest"],"primaryEvidenceTargetId":"vocab_toughest"}'::jsonb,'live'),
('u4_idea_storeys',4,'idea_set','{"originalIdea":"The new hotel next to the station has twelve storeys.","accurateParaphrases":["The new hotel beside the station has twelve floors.","There are twelve levels in the new hotel next to the station.","The new hotel by the railway station is twelve floors high."],"meaningInvariants":[{"type":"quantity","value":"twelve"}],"distractors":[{"text":"The new hotel next to the station has two storeys.","misconceptionCategory":"quantity_change"},{"text":"The new hotel next to the station has twelve rooms.","misconceptionCategory":"meaning_confusion"},{"text":"The old hotel next to the station has twelve storeys.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_storeys"],"primaryEvidenceTargetId":"vocab_storeys"}'::jsonb,'live'),
('u4_idea_accommodate',4,'idea_set','{"originalIdea":"The new stadium can accommodate fifty thousand fans.","accurateParaphrases":["The new stadium has enough space for fifty thousand fans.","Fifty thousand supporters can fit into the new stadium.","The new stadium is able to hold fifty thousand fans."],"meaningInvariants":[{"type":"quantity","value":"fifty thousand"}],"distractors":[{"text":"The new stadium has enough space for five thousand fans.","misconceptionCategory":"quantity_change"},{"text":"The new stadium will be built for fifty thousand fans.","misconceptionCategory":"time_change"},{"text":"The new stadium has to turn away fifty thousand fans.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_accommodate"],"primaryEvidenceTargetId":"vocab_accommodate"}'::jsonb,'live'),
('u4_idea_luxury',4,'idea_set','{"originalIdea":"The hotel offers its guests a life of luxury at a very high price.","accurateParaphrases":["The hotel gives its guests lavish surroundings for a very high price.","Guests at the hotel enjoy expensive, high-class living, and they pay a lot for it.","Guests at the hotel pay a very high price for a lavish lifestyle."],"meaningInvariants":[{"type":"quantity","value":"a very high price"}],"distractors":[{"text":"The hotel offers its guests a simple life at a very low price.","misconceptionCategory":"polarity_change"},{"text":"The hotel offers its guests a life of luxury at a fair price.","misconceptionCategory":"degree_change"},{"text":"The hotel offers its staff a life of luxury at a very high price.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_luxury"],"primaryEvidenceTargetId":"vocab_luxury"}'::jsonb,'live'),
('u4_idea_altitude',4,'idea_set','{"originalIdea":"The aeroplane reached a cruising altitude of ten thousand metres.","accurateParaphrases":["The plane climbed to a cruising height of ten thousand metres above sea level.","Ten thousand metres above sea level was the height at which the plane cruised.","The aircraft levelled out at ten thousand metres above sea level."],"meaningInvariants":[{"type":"quantity","value":"ten thousand metres"}],"distractors":[{"text":"The aeroplane reached a cruising speed of ten thousand kilometres an hour.","misconceptionCategory":"meaning_confusion"},{"text":"The aeroplane reached a cruising altitude of one thousand metres.","misconceptionCategory":"quantity_change"},{"text":"The aeroplane dropped from a cruising altitude of ten thousand metres.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_altitude"],"primaryEvidenceTargetId":"vocab_altitude"}'::jsonb,'live'),
('u4_idea_landscape',4,'idea_set','{"originalIdea":"The new wind farm has changed the landscape of the valley.","accurateParaphrases":["The new wind farm has altered the scenery of the valley.","The countryside in the valley has been changed by the new wind farm.","The new wind farm has made the valley look different."],"meaningInvariants":[{"type":"cause_effect","value":"the wind farm changed how the valley looks"}],"distractors":[{"text":"The new wind farm has left the landscape of the valley unchanged.","misconceptionCategory":"polarity_change"},{"text":"The new wind farm has slightly improved the weather in the valley.","misconceptionCategory":"meaning_confusion"},{"text":"The new wind farm will change the landscape of the valley next year.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_landscape"],"primaryEvidenceTargetId":"vocab_landscape"}'::jsonb,'live'),
('u4_idea_passenger',4,'idea_set','{"originalIdea":"Every passenger must show a ticket before boarding the ferry.","accurateParaphrases":["All travellers must show a ticket before they get on the ferry.","Each person travelling on the ferry has to show a ticket before boarding.","Before getting on the ferry, everyone who is travelling must show a ticket."],"meaningInvariants":[{"type":"quantity","value":"every traveller"}],"distractors":[{"text":"Only some passengers must show a ticket before boarding the ferry.","misconceptionCategory":"quantity_change"},{"text":"Every passenger must buy a ticket after boarding the ferry.","misconceptionCategory":"time_change"},{"text":"Every driver must show a ticket before boarding the ferry.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_passenger"],"primaryEvidenceTargetId":"vocab_passenger"}'::jsonb,'live'),
('u4_idea_engineer',4,'idea_set','{"originalIdea":"The aircraft engineer found a fault in the left wing before take-off.","accurateParaphrases":["The technical expert who maintains the aircraft discovered a problem in the left wing before it took off.","Before take-off, the person responsible for the aircraft’s machinery found a fault in the left wing.","A trained technician noticed a defect in the left wing before the plane departed."],"meaningInvariants":[{"type":"time","value":"before take-off"}],"distractors":[{"text":"The aircraft engineer found a fault in the left wing after landing.","misconceptionCategory":"time_change"},{"text":"The aircraft engineer fixed the fault in the left wing before take-off.","misconceptionCategory":"added_information"},{"text":"The pilot found a fault in the left wing before take-off.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_engineer"],"primaryEvidenceTargetId":"vocab_engineer"}'::jsonb,'live'),
('u4_idea_pilot',4,'idea_set','{"originalIdea":"The pilot decided to land at a different airport because of the storm.","accurateParaphrases":["The person flying the plane chose to land at another airport because of the storm.","Because of the storm, the aircraft’s captain decided to land somewhere else.","The storm made the person in charge of the aircraft choose a different airport for landing."],"meaningInvariants":[{"type":"cause_effect","value":"the storm caused the change of airport"}],"distractors":[{"text":"The pilot decided to land at a different airport because of an engine problem.","misconceptionCategory":"cause_effect_change"},{"text":"The pilot decided to land at the same airport despite the storm.","misconceptionCategory":"polarity_change"},{"text":"The passengers decided to land at a different airport because of the storm.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_pilot"],"primaryEvidenceTargetId":"vocab_pilot"}'::jsonb,'live'),
('u4_idea_airship',4,'idea_set','{"originalIdea":"Early airships were slower than aeroplanes but could stay in the air for several days.","accurateParaphrases":["The first gas-filled steerable aircraft moved more slowly than planes but could remain airborne for days.","Although they travelled at lower speeds than aeroplanes, early lighter-than-air craft could fly continuously for several days.","Early lighter-than-air aircraft were not as fast as planes, yet they could stay up for days at a time."],"meaningInvariants":[{"type":"comparison","value":"slower than aeroplanes but able to stay up for days"}],"distractors":[{"text":"Early airships were faster than aeroplanes but could stay in the air for only a few hours.","misconceptionCategory":"comparison_change"},{"text":"Early airships were slower than aeroplanes and could stay in the air for only a few minutes.","misconceptionCategory":"time_change"},{"text":"Early airships were slower than aeroplanes but could carry no passengers.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_airship"],"primaryEvidenceTargetId":"vocab_airship"}'::jsonb,'live'),
('u4_idea_launch',4,'idea_set','{"originalIdea":"The company will launch its new electric bus next month.","accurateParaphrases":["The company will introduce its new electric bus next month.","Next month, the company will put its new electric bus into service.","The company will bring out its new electric bus next month."],"meaningInvariants":[{"type":"time","value":"next month"}],"distractors":[{"text":"The company launched its new electric bus last month.","misconceptionCategory":"time_change"},{"text":"The company will cancel its new electric bus next month.","misconceptionCategory":"polarity_change"},{"text":"The company will repair its new electric bus next month.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_launch"],"primaryEvidenceTargetId":"vocab_launch"}'::jsonb,'live'),
('u4_idea_height',4,'idea_set','{"originalIdea":"The maximum height of vehicles in the tunnel is four metres.","accurateParaphrases":["Vehicles in the tunnel must not be taller than four metres.","No vehicle taller than four metres is allowed in the tunnel.","The tunnel only allows vehicles that are four metres tall or less."],"meaningInvariants":[{"type":"quantity","value":"four metres"}],"distractors":[{"text":"The maximum width of vehicles in the tunnel is four metres.","misconceptionCategory":"meaning_confusion"},{"text":"The maximum height of vehicles in the tunnel is forty metres.","misconceptionCategory":"quantity_change"},{"text":"Vehicles in the tunnel must be at least four metres tall.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_height"],"primaryEvidenceTargetId":"vocab_height"}'::jsonb,'live'),
('u4_idea_anxious',4,'idea_set','{"originalIdea":"The anxious passenger asked the crew if the storm would delay the flight.","accurateParaphrases":["The nervous traveller asked the crew whether the storm would delay the flight.","A worried passenger asked the crew if the flight would be delayed by the storm.","Feeling nervous, the passenger asked the crew whether bad weather would hold up the flight."],"meaningInvariants":[{"type":"cause_effect","value":"asks whether the storm will delay the flight"}],"distractors":[{"text":"The anxious passenger told the crew that the storm had delayed the flight.","misconceptionCategory":"cause_effect_change"},{"text":"The excited passenger asked the crew if the storm would delay the flight.","misconceptionCategory":"meaning_confusion"},{"text":"The anxious passenger asked the crew if the flight would arrive early.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_anxious"],"primaryEvidenceTargetId":"vocab_anxious"}'::jsonb,'live'),
('u4_idea_vehicle',4,'idea_set','{"originalIdea":"Every vehicle entering the city centre must pay a daily charge.","accurateParaphrases":["All cars, buses and lorries entering the city centre have to pay a daily fee.","A daily fee must be paid for each means of transport that goes into the city centre.","Anything that drives into the city centre must pay a charge every day."],"meaningInvariants":[{"type":"quantity","value":"every one pays"}],"distractors":[{"text":"Only large vehicles entering the city centre must pay a daily charge.","misconceptionCategory":"quantity_change"},{"text":"Every vehicle entering the city centre must pay a monthly charge.","misconceptionCategory":"time_change"},{"text":"Every vehicle leaving the city centre must pay a daily charge.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_vehicle"],"primaryEvidenceTargetId":"vocab_vehicle"}'::jsonb,'live'),
('u4_idea_pollution',4,'idea_set','{"originalIdea":"The council wants to reduce pollution in the city centre by banning older diesel lorries.","accurateParaphrases":["To make the city centre cleaner, the council intends to ban older diesel lorries.","By banning older diesel lorries, the council hopes to reduce contamination in the city centre.","The council plans to cut harmful damage to the air in the city centre by not allowing old diesel lorries."],"meaningInvariants":[{"type":"cause_effect","value":"banning old lorries to reduce harmful substances"}],"distractors":[{"text":"The council wants to increase pollution in the city centre by banning older diesel lorries.","misconceptionCategory":"polarity_change"},{"text":"The council wants to reduce pollution in the city centre by allowing older diesel lorries.","misconceptionCategory":"cause_effect_change"},{"text":"The council wants to reduce traffic noise in the city centre by banning older diesel lorries.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_pollution"],"primaryEvidenceTargetId":"vocab_pollution"}'::jsonb,'live'),
('u4_idea_destination',4,'idea_set','{"originalIdea":"Passengers can check the destination of each train on the departure board.","accurateParaphrases":["Travellers can see where each train is going on the departure board.","Passengers can find out the place each train is travelling to by looking at the departure board.","The departure board tells travellers the final stop of every train."],"meaningInvariants":[{"type":"quantity","value":"each train"}],"distractors":[{"text":"Passengers can check the speed of each train on the departure board.","misconceptionCategory":"meaning_confusion"},{"text":"Passengers can check the destination of only one train on the departure board.","misconceptionCategory":"quantity_change"},{"text":"Passengers can check the destination of each train after it has left the station.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_destination"],"primaryEvidenceTargetId":"vocab_destination"}'::jsonb,'live'),
('u4_idea_spacious',4,'idea_set','{"originalIdea":"The new train is more spacious than the old one, so passengers have more room for their luggage.","accurateParaphrases":["The new train has more room inside than the old one, so travellers can fit more luggage.","Passengers have extra space for their bags on the new train, which is roomier than the old one.","Because the new train is roomier than the old train, passengers can carry more luggage."],"meaningInvariants":[{"type":"comparison","value":"the new train has more room than the old one"}],"distractors":[{"text":"The new train is less spacious than the old one, so passengers have less room for their luggage.","misconceptionCategory":"polarity_change"},{"text":"The new train is just as spacious as the old one, so passengers have the same room for their luggage.","misconceptionCategory":"comparison_change"},{"text":"The new train is faster than the old one, so passengers reach their destination sooner.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_spacious"],"primaryEvidenceTargetId":"vocab_spacious"}'::jsonb,'live'),
('u4_idea_efficiently',4,'idea_set','{"originalIdea":"The new system allows the airline to process passengers efficiently.","accurateParaphrases":["The new system lets the airline deal with passengers without wasting time or effort.","With the new system, the airline can handle its passengers in a well-run, economical way.","Passengers can be processed by the airline in a way that wastes very little time with the new system."],"meaningInvariants":[{"type":"degree","value":"with very little waste"}],"distractors":[{"text":"The new system allows the airline to process passengers very slowly.","misconceptionCategory":"polarity_change"},{"text":"The new system allows the airport to process luggage efficiently.","misconceptionCategory":"meaning_confusion"},{"text":"The new system allows the airline to process passengers efficiently but at a much higher cost.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_efficiently"],"primaryEvidenceTargetId":"vocab_efficiently"}'::jsonb,'live'),
('u4_idea_demand',4,'idea_set','{"originalIdea":"Demand for cheap train tickets rises sharply at the start of the school holidays.","accurateParaphrases":["Many more people want cheap train tickets at the start of the school holidays.","At the start of the school holidays, the public’s wish for cheap train tickets increases greatly.","The need for cheap train tickets goes up quickly when the school holidays begin."],"meaningInvariants":[{"type":"time","value":"at the start of the school holidays"}],"distractors":[{"text":"Demand for cheap train tickets falls sharply at the start of the school holidays.","misconceptionCategory":"polarity_change"},{"text":"Demand for cheap train tickets rises slightly at the start of the school holidays.","misconceptionCategory":"degree_change"},{"text":"Demand for cheap train tickets rises sharply at the end of the school holidays.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_demand_4"],"primaryEvidenceTargetId":"vocab_demand_4"}'::jsonb,'live'),
('u4_idea_invention',4,'idea_set','{"originalIdea":"The invention of the railway changed the way people travelled in the nineteenth century.","accurateParaphrases":["The creation of the railway transformed how people travelled in the nineteenth century.","Travel in the nineteenth century was changed by the creation of the railway.","When the railway was first created, it changed how people travelled in the nineteenth century."],"meaningInvariants":[{"type":"cause_effect","value":"the new railway changed how people travelled"}],"distractors":[{"text":"The invention of the railway changed the way people travelled in the twentieth century.","misconceptionCategory":"time_change"},{"text":"The discovery of the railway changed the way people travelled in the nineteenth century.","misconceptionCategory":"meaning_confusion"},{"text":"The invention of the railway had no effect on the way people travelled in the nineteenth century.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_invention"],"primaryEvidenceTargetId":"vocab_invention"}'::jsonb,'live'),
('u4_idea_machinery',4,'idea_set','{"originalIdea":"The factory has installed new machinery to produce car parts more quickly.","accurateParaphrases":["The factory has put in new powered devices so that it can make car parts faster.","New mechanical devices have been fitted in the factory so that car parts are produced faster.","The factory now has newly installed powered devices that help it make car parts more quickly."],"meaningInvariants":[{"type":"cause_effect","value":"new devices to produce parts faster"}],"distractors":[{"text":"The factory has installed new machinery to produce car parts more slowly.","misconceptionCategory":"polarity_change"},{"text":"The factory has installed new machinery to produce aeroplane parts more quickly.","misconceptionCategory":"meaning_confusion"},{"text":"The factory plans to install new machinery to produce car parts more quickly.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_machinery"],"primaryEvidenceTargetId":"vocab_machinery"}'::jsonb,'live'),
('u4_idea_advertisement',4,'idea_set','{"originalIdea":"The airline withdrew its advertisement because it made a false claim about ticket prices.","accurateParaphrases":["The airline took away its promotional message because it gave false information about ticket prices.","Because its promotion contained a false claim about ticket prices, the airline removed it.","The airline stopped using its promotional message after it wrongly described its ticket prices."],"meaningInvariants":[{"type":"cause_effect","value":"a false claim caused the withdrawal"}],"distractors":[{"text":"The airline withdrew its advertisement because it was too expensive to show.","misconceptionCategory":"cause_effect_change"},{"text":"The airline kept its advertisement even though it made a false claim about ticket prices.","misconceptionCategory":"polarity_change"},{"text":"The airline withdrew its timetable because it made a false claim about ticket prices.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_advertisement_4"],"primaryEvidenceTargetId":"vocab_advertisement_4"}'::jsonb,'live'),
('u4_idea_enormous',4,'idea_set','{"originalIdea":"The enormous cargo ship was too wide to pass through the old canal.","accurateParaphrases":["The extremely large cargo ship could not fit through the old canal because it was too wide.","The old canal was not wide enough for the huge cargo ship.","Because of its great width, the gigantic cargo ship could not use the old canal."],"meaningInvariants":[{"type":"cause_effect","value":"too wide for the canal"}],"distractors":[{"text":"The enormous cargo ship was too heavy to pass through the old canal.","misconceptionCategory":"cause_effect_change"},{"text":"The tiny cargo ship was too wide to pass through the old canal.","misconceptionCategory":"degree_change"},{"text":"The enormous cargo ship passed easily through the old canal.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_enormous"],"primaryEvidenceTargetId":"vocab_enormous"}'::jsonb,'live'),
('u4_idea_equipment',4,'idea_set','{"originalIdea":"All emergency equipment on the ferry is checked before every voyage.","accurateParaphrases":["Every piece of emergency gear on the ferry is inspected before each journey.","Before each voyage, all the emergency tools and devices on the ferry are checked.","The ferry’s emergency gear is all examined before every trip."],"meaningInvariants":[{"type":"quantity","value":"all of it, before every voyage"}],"distractors":[{"text":"Some emergency equipment on the ferry is checked before every voyage.","misconceptionCategory":"quantity_change"},{"text":"All emergency equipment on the ferry is checked after every voyage.","misconceptionCategory":"time_change"},{"text":"All emergency staff on the ferry are trained before every voyage.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_equipment_4"],"primaryEvidenceTargetId":"vocab_equipment_4"}'::jsonb,'live'),
('u4_idea_collision',4,'idea_set','{"originalIdea":"The collision between the bus and the lorry happened early in the morning.","accurateParaphrases":["The crash between the bus and the lorry took place early in the morning.","Early in the morning, the bus and the lorry were involved in a crash.","The bus and the lorry hit each other early in the morning."],"meaningInvariants":[{"type":"time","value":"early in the morning"}],"distractors":[{"text":"The collision between the bus and the lorry happened late at night.","misconceptionCategory":"time_change"},{"text":"The race between the bus and the lorry happened early in the morning.","misconceptionCategory":"meaning_confusion"},{"text":"The collision between the bus and the lorry was prevented early in the morning.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_collision"],"primaryEvidenceTargetId":"vocab_collision"}'::jsonb,'live'),
('u4_idea_organisation',4,'idea_set','{"originalIdea":"The organisation was set up in 1950 to improve road safety.","accurateParaphrases":["The group was founded in 1950 with the aim of making roads safer.","In 1950, people came together to form a group whose aim was safer roads.","The association was established in 1950 in order to make the roads safer."],"meaningInvariants":[{"type":"time","value":"1950"}],"distractors":[{"text":"The organisation was set up in 1990 to improve road safety.","misconceptionCategory":"time_change"},{"text":"The organisation was set up in 1950 to improve railway comfort.","misconceptionCategory":"meaning_confusion"},{"text":"The organisation was closed in 1950 after failing to improve road safety.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_organisation"],"primaryEvidenceTargetId":"vocab_organisation"}'::jsonb,'live'),
('u4_idea_participant',4,'idea_set','{"originalIdea":"Every participant in the road safety trial must wear a helmet.","accurateParaphrases":["All the people taking part in the road safety trial have to wear a helmet.","Everyone involved in the road safety trial is required to wear a helmet.","Each person who takes part in the road safety trial must put on a helmet."],"meaningInvariants":[{"type":"quantity","value":"everyone wears a helmet"}],"distractors":[{"text":"Only the winner of the road safety trial must wear a helmet.","misconceptionCategory":"quantity_change"},{"text":"Every spectator at the road safety trial must wear a helmet.","misconceptionCategory":"meaning_confusion"},{"text":"Every participant in the road safety trial may choose not to wear a helmet.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_participant_4"],"primaryEvidenceTargetId":"vocab_participant_4"}'::jsonb,'live'),
('u4_idea_livelihood',4,'idea_set','{"originalIdea":"The closure of the railway workshop threatened the livelihood of hundreds of families.","accurateParaphrases":["Hundreds of families risked losing their means of earning a living when the railway workshop closed.","Closing the railway workshop put the income of hundreds of families at risk.","The shutting of the railway workshop endangered how hundreds of families earned money."],"meaningInvariants":[{"type":"cause_effect","value":"the closure put hundreds of families’ income at risk"}],"distractors":[{"text":"The closure of the railway workshop created new jobs for hundreds of families.","misconceptionCategory":"polarity_change"},{"text":"The closure of the railway workshop threatened the holidays of hundreds of families.","misconceptionCategory":"meaning_confusion"},{"text":"The closure of the railway workshop threatened the livelihood of a few families.","misconceptionCategory":"quantity_change"}],"linkedVocabularyIds":["vocab_livelihood"],"primaryEvidenceTargetId":"vocab_livelihood"}'::jsonb,'live'),
('u4_idea_fatality',4,'idea_set','{"originalIdea":"The police said that the accident had caused one fatality.","accurateParaphrases":["The police stated that one person had died in the accident.","According to the police, the accident had resulted in a single death.","One person lost their life in the accident, the police said."],"meaningInvariants":[{"type":"quantity","value":"one"}],"distractors":[{"text":"The police said that the accident had caused three fatalities.","misconceptionCategory":"quantity_change"},{"text":"The police said that the accident had caused no fatalities.","misconceptionCategory":"polarity_change"},{"text":"The police said that the accident had caused one injury.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_fatality"],"primaryEvidenceTargetId":"vocab_fatality"}'::jsonb,'live'),
('u4_idea_initiative',4,'idea_set','{"originalIdea":"The new initiative aims to cut the number of road accidents near schools.","accurateParaphrases":["The new scheme is intended to reduce accidents on roads near schools.","The purpose of the new programme is to lower the number of road accidents close to schools.","A new plan has been introduced in order to have fewer accidents on roads near schools."],"meaningInvariants":[{"type":"cause_effect","value":"the aim is to cut accidents near schools"}],"distractors":[{"text":"The new initiative aims to increase the number of road accidents near schools.","misconceptionCategory":"polarity_change"},{"text":"The new initiative aims to cut the number of road accidents near hospitals.","misconceptionCategory":"meaning_confusion"},{"text":"The new initiative cut the number of road accidents near schools last year.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_initiative"],"primaryEvidenceTargetId":"vocab_initiative"}'::jsonb,'live'),
('u4_idea_campaign',4,'idea_set','{"originalIdea":"The campaign persuaded thousands of drivers to slow down near schools.","accurateParaphrases":["Thousands of drivers were convinced to reduce speed near schools by the organised effort.","Because of the public effort, thousands of drivers began to drive more slowly near schools.","The public-awareness drive led thousands of drivers to slow down near schools."],"meaningInvariants":[{"type":"cause_effect","value":"the campaign led drivers to slow down"}],"distractors":[{"text":"The campaign forced thousands of drivers to leave their cars near schools.","misconceptionCategory":"cause_effect_change"},{"text":"The campaign persuaded a few drivers to slow down near schools.","misconceptionCategory":"quantity_change"},{"text":"The campaign persuaded thousands of drivers to speed up near schools.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_campaign"],"primaryEvidenceTargetId":"vocab_campaign"}'::jsonb,'live'),
('u4_idea_pothole',4,'idea_set','{"originalIdea":"The council has promised to repair every pothole on the main road this month.","accurateParaphrases":["The council has pledged to mend all the holes in the main road this month.","This month, the council intends to fix each hole in the surface of the main road.","All the road-surface holes on the main road will be repaired by the council this month, it has promised."],"meaningInvariants":[{"type":"quantity","value":"every one, this month"}],"distractors":[{"text":"The council has promised to repair some potholes on the main road this month.","misconceptionCategory":"quantity_change"},{"text":"The council has promised to build a new main road this month.","misconceptionCategory":"meaning_confusion"},{"text":"The council has promised to repair every pothole on the main road next year.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_pothole"],"primaryEvidenceTargetId":"vocab_pothole"}'::jsonb,'live'),
('u4_idea_trauma',4,'idea_set','{"originalIdea":"The survivors were offered counselling to help them deal with the trauma of the accident.","accurateParaphrases":["The people who survived were given counselling so that they could cope with the lasting shock of the accident.","Counselling was offered to survivors to help them manage the emotional effects of the accident.","To help them handle the distress caused by the accident, the survivors were offered counselling."],"meaningInvariants":[{"type":"cause_effect","value":"counselling offered to help with emotional effects"}],"distractors":[{"text":"The survivors were refused counselling to help them deal with the trauma of the accident.","misconceptionCategory":"polarity_change"},{"text":"The survivors were offered compensation to help them deal with the cost of the accident.","misconceptionCategory":"meaning_confusion"},{"text":"The survivors were offered counselling before the accident.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_trauma"],"primaryEvidenceTargetId":"vocab_trauma"}'::jsonb,'live'),
('u4_idea_measures',4,'idea_set','{"originalIdea":"The council took emergency measures to clear the snow from the roads.","accurateParaphrases":["The council acted urgently to remove the snow from the roads.","Urgent action was taken by the council to clear snow off the roads.","The council did what it could at once to get the snow off the roads."],"meaningInvariants":[{"type":"degree","value":"urgent action"}],"distractors":[{"text":"The council took emergency measures to build new roads in the snow.","misconceptionCategory":"meaning_confusion"},{"text":"The council took no emergency measures to clear the snow from the roads.","misconceptionCategory":"polarity_change"},{"text":"The council plans to take emergency measures to clear the snow from the roads next winter.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_measures"],"primaryEvidenceTargetId":"vocab_measures"}'::jsonb,'live'),
('u4_idea_estimate',4,'idea_set','{"originalIdea":"Officials estimate that the new tunnel will carry twenty thousand vehicles a day.","accurateParaphrases":["Officials calculate roughly that twenty thousand vehicles a day will use the new tunnel.","According to officials’ rough calculations, the new tunnel will carry around twenty thousand vehicles daily.","Officials believe, though they cannot be exact, that the new tunnel will carry about twenty thousand vehicles every day."],"meaningInvariants":[{"type":"quantity","value":"about twenty thousand a day"}],"distractors":[{"text":"Officials guarantee that the new tunnel will carry exactly twenty thousand vehicles a day.","misconceptionCategory":"degree_change"},{"text":"Officials estimate that the new tunnel will carry two thousand vehicles a day.","misconceptionCategory":"quantity_change"},{"text":"Officials estimate that the old tunnel carried twenty thousand vehicles a day.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_estimate"],"primaryEvidenceTargetId":"vocab_estimate"}'::jsonb,'live'),
('u4_idea_regulation',4,'idea_set','{"originalIdea":"A new regulation requires all cyclists to use lights after dark.","accurateParaphrases":["An official rule now says that every cyclist must have lights when it is dark.","All cyclists are required by a new official rule to use lights once it is dark.","According to a new rule from the authorities, cyclists must use lights at night."],"meaningInvariants":[{"type":"quantity","value":"all cyclists, after dark"}],"distractors":[{"text":"A new regulation advises some cyclists to use lights after dark.","misconceptionCategory":"quantity_change"},{"text":"A new regulation requires all cyclists to use lights before dark.","misconceptionCategory":"time_change"},{"text":"A new regulation forbids all cyclists from using lights after dark.","misconceptionCategory":"polarity_change"}],"linkedVocabularyIds":["vocab_regulation"],"primaryEvidenceTargetId":"vocab_regulation"}'::jsonb,'live'),
('u4_idea_operate',4,'idea_set','{"originalIdea":"Only trained staff may operate the cranes at the port.","accurateParaphrases":["Only people who have been trained are permitted to control the port’s cranes.","The cranes at the port may be controlled by trained staff alone.","Staff must be trained before they are allowed to work the cranes at the port."],"meaningInvariants":[{"type":"quantity","value":"only trained staff"}],"distractors":[{"text":"Any member of staff may operate the cranes at the port.","misconceptionCategory":"quantity_change"},{"text":"Only trained staff may repair the cranes at the port.","misconceptionCategory":"meaning_confusion"},{"text":"Only trained staff may operate the cranes at the airport.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_operate"],"primaryEvidenceTargetId":"vocab_operate"}'::jsonb,'live'),
('u4_idea_detain',4,'idea_set','{"originalIdea":"Police detained the driver for two hours while they checked his documents.","accurateParaphrases":["The driver was held by the police for two hours while his documents were checked.","For two hours, the police kept the driver in custody while they examined his papers.","The police held the driver for two hours until his documents had been checked."],"meaningInvariants":[{"type":"quantity","value":"two hours"}],"distractors":[{"text":"Police detained the driver for four hours while they checked his documents.","misconceptionCategory":"quantity_change"},{"text":"Police released the driver after two hours, once they had checked his documents.","misconceptionCategory":"polarity_change"},{"text":"Police delayed the driver for two hours because of roadworks.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_detain"],"primaryEvidenceTargetId":"vocab_detain"}'::jsonb,'live'),
('u4_idea_offences',4,'idea_set','{"originalIdea":"The number of driving offences fell by ten per cent last year.","accurateParaphrases":["Drivers broke the law ten per cent less often last year.","Last year, there was a ten per cent fall in the number of illegal acts by drivers.","Illegal acts by drivers decreased by ten per cent over the past year."],"meaningInvariants":[{"type":"quantity","value":"fell by ten per cent"}],"distractors":[{"text":"The number of driving offences rose by ten per cent last year.","misconceptionCategory":"polarity_change"},{"text":"The number of driving offences fell by twenty per cent last year.","misconceptionCategory":"quantity_change"},{"text":"The number of driving lessons fell by ten per cent last year.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_offences"],"primaryEvidenceTargetId":"vocab_offences"}'::jsonb,'live'),
('u4_idea_provisional',4,'idea_set','{"originalIdea":"The provisional date for opening the tunnel is March, but it may change.","accurateParaphrases":["The tunnel is expected to open in March, although that date is not yet final.","March is the temporary date for the opening of the tunnel, and it could change.","For now, the tunnel is due to open in March, but the date may be changed."],"meaningInvariants":[{"type":"time","value":"March, not yet final"}],"distractors":[{"text":"The final date for opening the tunnel is March, and it will not change.","misconceptionCategory":"degree_change"},{"text":"The provisional date for opening the tunnel is December, but it may change.","misconceptionCategory":"time_change"},{"text":"The provisional date for closing the tunnel is March, but it may change.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_provisional"],"primaryEvidenceTargetId":"vocab_provisional"}'::jsonb,'live'),
('u4_idea_enforcement',4,'idea_set','{"originalIdea":"Stricter enforcement of the speed limit reduced accidents outside the school.","accurateParaphrases":["Making sure drivers obeyed the speed limit more strictly led to fewer accidents outside the school.","Because the speed limit was policed more strictly, there were fewer accidents outside the school.","There were fewer accidents outside the school after drivers were made to obey the speed limit more strictly."],"meaningInvariants":[{"type":"cause_effect","value":"stricter checking led to fewer accidents"}],"distractors":[{"text":"Stricter enforcement of the speed limit increased accidents outside the school.","misconceptionCategory":"polarity_change"},{"text":"Stricter enforcement of the speed limit reduced accidents outside the hospital.","misconceptionCategory":"meaning_confusion"},{"text":"Fewer accidents outside the school led to stricter enforcement of the speed limit.","misconceptionCategory":"cause_effect_change"}],"linkedVocabularyIds":["vocab_enforcement"],"primaryEvidenceTargetId":"vocab_enforcement"}'::jsonb,'live'),
('u4_idea_statistics',4,'idea_set','{"originalIdea":"Official statistics show that bus passenger numbers rose by five per cent in 2025.","accurateParaphrases":["Official figures show a five per cent increase in the number of bus passengers in 2025.","According to official figures, five per cent more people travelled by bus in 2025.","The number of people using buses grew by five per cent in 2025, according to the official figures."],"meaningInvariants":[{"type":"quantity","value":"rose by five per cent, 2025"}],"distractors":[{"text":"Official statistics show that bus passenger numbers fell by five per cent in 2025.","misconceptionCategory":"polarity_change"},{"text":"Official statistics show that bus passenger numbers rose by fifteen per cent in 2025.","misconceptionCategory":"quantity_change"},{"text":"Official statistics show that bus passenger numbers rose by five per cent in 2015.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_statistics"],"primaryEvidenceTargetId":"vocab_statistics"}'::jsonb,'live'),
('u4_idea_safety',4,'idea_set','{"originalIdea":"The new barriers have improved the safety of pedestrians on the bridge.","accurateParaphrases":["Pedestrians on the bridge are now better protected from danger because of the new barriers.","Because of the new barriers, people walking on the bridge face less risk of injury.","The new barriers have made walking on the bridge less dangerous for pedestrians."],"meaningInvariants":[{"type":"cause_effect","value":"barriers improved protection"}],"distractors":[{"text":"The new barriers have reduced the number of pedestrians on the bridge.","misconceptionCategory":"meaning_confusion"},{"text":"The new barriers have made pedestrians on the bridge less protected.","misconceptionCategory":"polarity_change"},{"text":"Pedestrians’ improved protection caused the new barriers to be built on the bridge.","misconceptionCategory":"cause_effect_change"}],"linkedVocabularyIds":["vocab_safety"],"primaryEvidenceTargetId":"vocab_safety"}'::jsonb,'live'),
('u4_idea_sustainability',4,'idea_set','{"originalIdea":"The airline aims to improve its sustainability by using less fuel.","accurateParaphrases":["The airline hopes to do less harm to the environment by using less fuel.","By using less fuel, the airline wants to become kinder to the environment.","The airline intends to use fewer resources, so that its flights damage the environment less."],"meaningInvariants":[{"type":"cause_effect","value":"less fuel to do less harm"}],"distractors":[{"text":"The airline aims to improve its sustainability by using more fuel.","misconceptionCategory":"polarity_change"},{"text":"The airline aims to reduce its costs by using less fuel.","misconceptionCategory":"meaning_confusion"},{"text":"The airline has already improved its sustainability by using less fuel.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_sustainability"],"primaryEvidenceTargetId":"vocab_sustainability"}'::jsonb,'live'),
('u4_idea_legislation',4,'idea_set','{"originalIdea":"Parliament passed new legislation last month to ban mobile phones while driving.","accurateParaphrases":["Last month, new laws were passed by Parliament to ban the use of mobile phones when driving.","Parliament approved new laws last month that forbid drivers to use mobile phones.","A ban on using mobile phones at the wheel became law last month, after Parliament passed it."],"meaningInvariants":[{"type":"time","value":"last month, ban on phones while driving"}],"distractors":[{"text":"Parliament rejected new legislation last month to ban mobile phones while driving.","misconceptionCategory":"polarity_change"},{"text":"Parliament passed new legislation last year to ban mobile phones while driving.","misconceptionCategory":"time_change"},{"text":"Parliament passed new legislation last month to ban loud music while driving.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_legislation"],"primaryEvidenceTargetId":"vocab_legislation"}'::jsonb,'live'),
('u4_idea_introduce',4,'idea_set','{"originalIdea":"The city will introduce free bus travel for students in September.","accurateParaphrases":["Free bus travel for students will begin in the city in September.","In September, the city will start offering students free bus travel.","From September, students in the city will be able to travel by bus for free."],"meaningInvariants":[{"type":"time","value":"September"}],"distractors":[{"text":"The city will end free bus travel for students in September.","misconceptionCategory":"polarity_change"},{"text":"The city will introduce free bus travel for pensioners in September.","misconceptionCategory":"meaning_confusion"},{"text":"The city will introduce free bus travel for students in December.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_introduce"],"primaryEvidenceTargetId":"vocab_introduce"}'::jsonb,'live'),
('u4_idea_innovative',4,'idea_set','{"originalIdea":"The company is famous for its innovative designs for electric bicycles.","accurateParaphrases":["The company is well known for its original and effective designs for electric bicycles.","Its original and effective electric bicycle designs have made the company famous.","People know the company for the new ideas in its designs for electric bicycles."],"meaningInvariants":[{"type":"degree","value":"original, effective designs"}],"distractors":[{"text":"The company is famous for its cheap designs for electric bicycles.","misconceptionCategory":"meaning_confusion"},{"text":"The company is famous for its traditional designs for electric bicycles.","misconceptionCategory":"polarity_change"},{"text":"The company is more innovative than every other company that makes electric bicycles.","misconceptionCategory":"comparison_change"}],"linkedVocabularyIds":["vocab_innovative"],"primaryEvidenceTargetId":"vocab_innovative"}'::jsonb,'live'),
('u4_writing_precision_breathtaking_a',4,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “very beautiful” with a more precise Unit 4 word or phrase.","sourceText":"From the cable car, we had a very beautiful view of the whole valley.","acceptedAnswers":["breathtaking"],"distractors":["plain","narrow","crowded"],"linkedVocabularyIds":["vocab_breathtaking"],"primaryEvidenceTargetId":"vocab_breathtaking"}'::jsonb,'live'),
('u4_writing_precision_breathtaking_b',4,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “amazing” with a more precise Unit 4 word or phrase.","sourceText":"The sunset over the runway was amazing, so the travellers took photographs.","acceptedAnswers":["breathtaking"],"distractors":["ordinary","noisy","familiar"],"linkedVocabularyIds":["vocab_breathtaking"],"primaryEvidenceTargetId":"vocab_breathtaking"}'::jsonb,'live'),
('u4_writing_precision_comfort_a',4,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “being physically relaxed” with a more precise Unit 4 word or phrase.","sourceText":"The coach has wide seats, so passengers can enjoy being physically relaxed on long journeys.","acceptedAnswers":["comfort","physical comfort"],"distractors":["danger","speed","silence"],"linkedVocabularyIds":["vocab_comfort"],"primaryEvidenceTargetId":"vocab_comfort"}'::jsonb,'live'),
('u4_writing_precision_comfort_b',4,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “ease and relaxation” with a more precise Unit 4 word or phrase.","sourceText":"The airline spends millions on seats that offer passengers ease and relaxation.","acceptedAnswers":["comfort"],"distractors":["speed","danger","information"],"linkedVocabularyIds":["vocab_comfort"],"primaryEvidenceTargetId":"vocab_comfort"}'::jsonb,'live'),
('u4_writing_precision_reality_a',4,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “the real situation” with a more precise Unit 4 word or phrase.","sourceText":"The brochure promised a calm crossing, but the real situation is that the ferry shakes badly.","acceptedAnswers":["the reality","reality"],"distractors":["the promise","the plan","the dream"],"linkedVocabularyIds":["vocab_reality"],"primaryEvidenceTargetId":"vocab_reality"}'::jsonb,'live'),
('u4_writing_precision_reality_b',4,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “how things really are” with a more precise Unit 4 word or phrase.","sourceText":"New drivers should think about how things really are on icy roads.","acceptedAnswers":["the reality","the reality of"],"distractors":["the colour","the price","the history"],"linkedVocabularyIds":["vocab_reality"],"primaryEvidenceTargetId":"vocab_reality"}'::jsonb,'live'),
('u4_writing_precision_toughest_a',4,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “the most difficult” with a more precise Unit 4 word or phrase.","sourceText":"For the cyclists, the most difficult part of the route is the final climb.","acceptedAnswers":["the toughest","toughest"],"distractors":["the shortest","the cheapest","the quietest"],"linkedVocabularyIds":["vocab_toughest"],"primaryEvidenceTargetId":"vocab_toughest"}'::jsonb,'live'),
('u4_writing_precision_toughest_b',4,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “hardest” with a more precise Unit 4 word or phrase.","sourceText":"Many pilots say that landing in strong wind is the hardest test of their skill.","acceptedAnswers":["toughest"],"distractors":["safest","quietest","cheapest"],"linkedVocabularyIds":["vocab_toughest"],"primaryEvidenceTargetId":"vocab_toughest"}'::jsonb,'live'),
('u4_writing_precision_storeys_a',4,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “floors” with a more precise Unit 4 word or phrase.","sourceText":"The new airport hotel has thirty floors and a restaurant on the roof.","acceptedAnswers":["storeys"],"distractors":["lifts","windows","doors"],"linkedVocabularyIds":["vocab_storeys"],"primaryEvidenceTargetId":"vocab_storeys"}'::jsonb,'live'),
('u4_writing_precision_storeys_b',4,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “levels” with a more precise Unit 4 word or phrase.","sourceText":"The car park beside the terminal has eight levels, and a lift connects them all.","acceptedAnswers":["storeys"],"distractors":["exits","tickets","barriers"],"linkedVocabularyIds":["vocab_storeys"],"primaryEvidenceTargetId":"vocab_storeys"}'::jsonb,'live'),
('u4_writing_precision_accommodate_a',4,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “has enough room for” with a more precise Unit 4 word or phrase.","sourceText":"The new ferry has enough room for two hundred cars and a thousand people.","acceptedAnswers":["can accommodate","accommodates"],"distractors":["can repair","can inspect","can follow"],"linkedVocabularyIds":["vocab_accommodate"],"primaryEvidenceTargetId":"vocab_accommodate"}'::jsonb,'live'),
